import java.util.*;
import java.io.*;

public class Main {
    static class Edge {
        int v, w, c, nx;
        Edge(int v, int w, int c, int nx) {
            this.v = v;
            this.w = w;
            this.c = c;
            this.nx = nx;
        }
    }

    static final int oo = 2139063143;
    static final int N = 5010000;
    static final int P = 1000000007;
    static final double eps = 1e-7;

    static List<Edge> edges = new ArrayList<>();
    static int[] head;
    static int tot;
    static int s, t;
    static int[] dist, flow, pre, last_edge;
    static boolean[] in_queue;

    static boolean spfa() {
        Arrays.fill(dist, Integer.MAX_VALUE);
        Arrays.fill(flow, 0);
        Arrays.fill(pre, 0);
        Arrays.fill(last_edge, 0);
        Arrays.fill(in_queue, false);
        Queue<Integer> q = new LinkedList<>();
        dist[s] = 0;
        flow[s] = Integer.MAX_VALUE;
        q.offer(s);
        in_queue[s] = true;
        while (!q.isEmpty()) {
            int u = q.poll();
            in_queue[u] = false;
            for (int kb = head[u]; kb != 0; kb = edges.get(kb - 1).nx) {
                Edge e = edges.get(kb - 1);
                int v = e.v, w = e.w, c = e.c;
                if (w > 0 && dist[v] > dist[u] + c) {
                    dist[v] = dist[u] + c;
                    flow[v] = Math.min(flow[u], w);
                    pre[v] = u;
                    last_edge[v] = kb;
                    if (!in_queue[v]) {
                        q.offer(v);
                        in_queue[v] = true;
                    }
                }
            }
        }
        return pre[t] != 0;
    }

    static int max_flow = 0, min_cost = 0;

    static void min_cost_max_flow() {
        while (spfa()) {
            int u = t;
            int f = flow[t];
            max_flow += f;
            min_cost += f * dist[t];
            while (u != s) {
                int e_idx = last_edge[u] - 1;
                Edge e = edges.get(e_idx);
                edges.set(e_idx, new Edge(e.v, e.w - f, e.c, e.nx));
                Edge rev = edges.get(e_idx ^ 1);
                edges.set(e_idx ^ 1, new Edge(rev.v, rev.w + f, rev.c, rev.nx));
                u = pre[u];
            }
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st;

        st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());
        int k = Integer.parseInt(st.nextToken());
        int c = Integer.parseInt(st.nextToken());
        int d = Integer.parseInt(st.nextToken());

        int B = Math.max(n, k);
        int size = n * (B * 2 + 1) + 2;
        s = n * (B * 2 + 1) + 1;
        t = s + 1;

        head = new int[size];
        Arrays.fill(head, 0);
        edges.clear();
        tot = 1;

        // Helper method to add edges
        BiConsumer<Integer, Integer> addEdge = (u, v) -> {
            edges.add(new Edge(v, 1, 0, head[u]));
            head[u] = edges.size();
        };

        // Read k
        st = new StringTokenizer(br.readLine());
        int[] xArr = new int[k + 1];
        for (int i = 1; i <= k; i++) {
            xArr[i] = Integer.parseInt(st.nextToken());
        }

        // Initialize arrays
        dist = new int[size];
        flow = new int[size];
        pre = new int[size];
        last_edge = new int[size];
        in_queue = new boolean[size];

        // Add edges from s to x
        for (int i = 1; i <= k; i++) {
            int x = xArr[i];
            edges.add(new Edge(x, 1, 0, head[s]));
            head[s] = edges.size();
        }

        // Add edge from n*(B*2)+1 to t
        edges.add(new Edge(t, Integer.MAX_VALUE, 0, head[n * (B * 2) + 1]));
        head[n * (B * 2) + 1] = edges.size();

        // Build layers
        for (int o = 0; o < B * 2; o++) {
            int from = o * n + 1;
            int to = (o + 1) * n + 1;
            edges.add(new Edge(to, Integer.MAX_VALUE, 0, head[from]));
            head[from] = edges.size();

            for (int i = 2; i <= n; i++) {
                int u = o * n + i;
                int v = (o + 1) * n + i;
                edges.add(new Edge(v, Integer.MAX_VALUE, 0, head[u]));
                head[u] = edges.size();

                // Add edge with cost c
                edges.add(new Edge(v, Integer.MAX_VALUE, c, head[u]));
                head[u] = edges.size();

                edges.add(new Edge(u, Integer.MAX_VALUE, c, head[v]));
                head[v] = edges.size();
            }
        }

        // Read m edges
        for (int _ = 0; _ < m; _++) {
            st = new StringTokenizer(br.readLine());
            int x = Integer.parseInt(st.nextToken());
            int y = Integer.parseInt(st.nextToken());
            for (int o = 0; o < B * 2; o++) {
                for (int i = 1; i <= k; i++) {
                    int cost = d * (2 * i - 1) + c;
                    int u1 = o * n + x;
                    int v1 = (o + 1) * n + y;
                    int u2 = o * n + y;
                    int v2 = (o + 1) * n + x;
                    edges.add(new Edge(v1, 1, cost, head[u1]));
                    head[u1] = edges.size();
                    edges.add(new Edge(v2, 1, cost, head[u2]));
                    head[u2] = edges.size();
                }
            }
        }

        min_cost_max_flow();

        System.out.println(min_cost);
    }
}
